function ahvDocNote(c) {
  const e = c.printedEvidence || {};
  const parts = [];
  if (e.number) parts.push("No. " + e.number);
  if (e.order) parts.push("Order " + e.order);
  if (e.printedValidFrom && e.printedValidThrough) parts.push("Valid " + e.printedValidFrom + " to " + e.printedValidThrough);
  else if (e.printedIssueDate && e.printedValidThrough) parts.push("Issued " + e.printedIssueDate + ", valid to " + e.printedValidThrough);
  else if (e.printedValidThrough) parts.push("Valid to " + e.printedValidThrough);
  else if (e.printedDate && e.printedPeriod) parts.push("Dated " + e.printedDate + ", " + e.printedPeriod);
  else if (e.issued) parts.push("Issued " + e.issued.replace(/(\d)(\D)/, "$1 $2"));
  return parts.join(" · ");
}

class Component extends DCLogic {
  state = { open: false, i: 0, zoom: false };
  componentDidMount() { document.documentElement.lang = 'en-US'; if (this.state.open) this.acquireLock(); }
  componentWillUnmount() { this._gone = true; this.releaseLock(); }
  // OWNER-REG-07 (iOS: closing the certificate viewer left scrolling stuck). One paired, idempotent lock: acquire saves
  // the exact prior inline overflow (value + priority) and the settled scroll position; release (close, Escape, unmount)
  // puts back only a lock this instance still holds, then the position. Pending focus timers are cancelled and a late
  // callback never focuses into a closed or unmounted viewer; focus never scrolls the page.
  acquireLock() {
    if (this._lock) return;
    const s = document.body.style;
    this._lock = { x: window.scrollX, y: window.scrollY, saved: ['overflow-x', 'overflow-y'].map((k) => [k, s.getPropertyValue(k), s.getPropertyPriority(k)]) };
    s.setProperty('overflow', 'hidden');
    // Escape also closes when a tap left focus on <body> (Safari does not focus tapped buttons, so the dialog's own
    // onKeyDown never sees the key); the dialog's handler runs first and prevents the default, so this never doubles
    this._onEsc = (e) => { if (e.key === 'Escape' && !e.defaultPrevented) this.closeViewer(); };
    document.addEventListener('keydown', this._onEsc);
  }
  releaseLock() {
    this.cancelFocus();
    if (this._onEsc) { document.removeEventListener('keydown', this._onEsc); this._onEsc = null; }
    const l = this._lock;
    if (!l) return;
    this._lock = null;
    const s = document.body.style;
    // only a lock this instance still holds: another owner's later value is left alone
    if (l.saved.every(([k]) => s.getPropertyValue(k) === 'hidden' && !s.getPropertyPriority(k))) for (const [k, v, p] of l.saved) { if (v) s.setProperty(k, v, p); else s.removeProperty(k); }
    if (window.scrollX !== l.x || window.scrollY !== l.y) window.scrollTo({ left: l.x, top: l.y, behavior: 'instant' });
  }
  cancelFocus() { if (this._focusTimer) { clearTimeout(this._focusTimer); this._focusTimer = null; } }
  focusLater(find, whenOpen) {
    this.cancelFocus();
    this._focusTimer = setTimeout(() => { this._focusTimer = null; if (this._gone || this.state.open !== whenOpen) return; const el = find(); if (el) el.focus({ preventScroll: true }); }, 30);
  }
  openAt(idx) {
    this._opener = idx;
    // Settle any in-flight smooth scroll (focus() from page top) instantly at the trigger before locking the page,
    // so the document position under the fixed overlay is stable (reproduced race, notes/about-us-page.md).
    const btn = document.querySelector('button[data-doc-index="' + idx + '"]');
    if (btn) { const r = btn.getBoundingClientRect(); if (r.top < 0 || r.bottom > window.innerHeight) window.scrollTo({ top: window.scrollY + r.top - Math.max(0, (window.innerHeight - r.height) / 2), behavior: 'instant' }); else window.scrollTo({ top: window.scrollY, behavior: 'instant' }); }
    this.setState({ open: true, i: idx, zoom: false });
    this.acquireLock();
    this.focusLater(() => document.getElementById('doc-close'), true);
  }
  closeViewer() {
    if (!this.state.open && !this._lock) return;
    const idx = this._opener != null ? this._opener : this.state.i; // focus returns to the trigger that opened the viewer
    this.setState({ open: false, zoom: false });
    this.releaseLock();
    this.focusLater(() => document.querySelector('button[data-doc-index="' + idx + '"]'), false);
  }
  renderVals() {
    const D = window.AHV_ABOUT;
    const A = 'https://ayurvedichealingvillage.com';
    const guard = () => {}; /* preview-only nav guard neutralised for the published site */
    if (!D) return { guard, quoteText: '', intro: {}, founder: {}, leadership: {}, directors: [], awards: {}, certificates: {}, documents: [], dlgDisplay: 'none', viewerImg: null, counter: '', curLabel: '', zoomLabel: 'Actual size', zoomPressed: 'false' };
    const docs = D.certificates.documents, n = docs.length, i = this.state.i, cur = docs[i] || docs[0];
    const go = (d) => this.setState(s => ({ i: (s.i + d + n) % n, zoom: false }));
    const zoom = this.state.zoom;
    // Viewer image built here so no placeholder request fires at parse time (Gallery limitation avoided) and state survives re-render.
    const viewerImg = this.state.open ? React.createElement('img', { id: 'doc-expanded', key: cur.src + (zoom ? 'z' : 'f'), src: cur.src, alt: cur.label, width: cur.width, height: cur.height,
      style: zoom ? { display: 'block', width: cur.width + 'px', maxWidth: 'none', height: 'auto', background: '#000' } : { display: 'block', width: 'auto', height: 'auto', maxWidth: '100%', maxHeight: 'calc(100vh - 240px)', objectFit: 'contain', background: '#000' } }) : null;
    return {
      guard, quoteText: D.quote.text,
      intro: { eyebrow: D.intro.eyebrow, heading: D.intro.heading, paragraph: D.intro.paragraph, linkText: D.intro.link.text, linkHref: A + D.intro.link.href },
      founder: { eyebrow: D.founder.eyebrow, heading: D.founder.heading, lead: D.founder.lead, paragraph: D.founder.paragraph, linkText: D.founder.link.text, linkHref: A + D.founder.link.href, name: D.founder.name, role: D.founder.role },
      leadership: { eyebrow: D.leadership.eyebrow, heading: D.leadership.heading },
      directors: D.leadership.directors.map(d => ({ id: d.id, name: d.name, role: d.role, paragraph: d.paragraph, portrait: d.portrait, hasLinkedin: !!d.linkedin, linkedinHref: d.linkedin ? d.linkedin.href : '', linkedinLabel: d.linkedin ? d.linkedin.label : '' })),
      awards: { eyebrow: D.awards.eyebrow, heading: D.awards.heading, lead: D.awards.lead, paragraph: D.awards.paragraph, linkText: D.awards.link.text, linkHref: A + D.awards.link.href },
      certificates: { eyebrow: D.certificates.eyebrow, heading: D.certificates.heading },
      documents: docs.map((c, idx) => ({ i: idx, src: c.src, label: c.label, note: ahvDocNote(c), width: c.width, height: c.height, open: () => this.openAt(idx) })),
      dlgDisplay: this.state.open ? 'flex' : 'none', viewerImg, counter: n ? 'Document ' + (i + 1) + ' of ' + n : '', curLabel: cur ? cur.label : '',
      zoomLabel: zoom ? 'Fit to screen' : 'Actual size', zoomPressed: zoom ? 'true' : 'false', toggleZoom: () => this.setState(s => ({ zoom: !s.zoom })),
      close: () => this.closeViewer(), prev: () => go(-1), next: () => go(1),
      dlgKey: (e) => {
        if (e.key === 'Escape') { e.preventDefault(); this.closeViewer(); return; }
        if (e.key === 'ArrowLeft') { e.preventDefault(); go(-1); return; }
        if (e.key === 'ArrowRight') { e.preventDefault(); go(1); return; }
        if (e.key === 'Tab') {
          const f = [...e.currentTarget.querySelectorAll('button')];
          const first = f[0], last = f[f.length - 1];
          if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
          else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
        }
      }
    };
  }
}
